{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-08",
  "sketch": {
    "components": ["Referral code generator", "Sign-up flow", "Referral redemption service", "Credit ledger"],
    "dataStores": ["User accounts", "Referral codes", "Credit balances"],
    "externalServices": [],
    "trustBoundaries": ["Unauthenticated sign-up endpoint", "Mobile client to backend"],
    "dataClasses": ["pii"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "Spoofing",
      "title": "Self-referral farming: one person creates many fake accounts to mint credits",
      "scenario": "Because sign-up needs only an email address and no verification, one person scripts hundreds of disposable or plus-addressed emails, redeems their own referral code each time, and collects $10 for the referrer plus $10 per fake account. With no device, payment or identity check, direct financial loss scales linearly with the number of fake sign-ups and is the dominant risk in this design.",
      "component": "Sign-up flow / referral redemption",
      "likelihood": 5,
      "impact": 4,
      "evidence": [
        {
          "quote": "When a new account signs up with the code, both accounts receive $10 credit. Sign-up only needs an email address."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-799", "CWE-840"],
      "plainLanguage": "Someone could sign up over and over with throwaway emails and give themselves free money.",
      "requirement": {
        "title": "Verify new accounts and limit referral payouts before crediting",
        "given": "a new account signs up using a referral code",
        "when": "the referral reward would be granted",
        "then": "credit is only issued after the email address is proven (verification link) and the account passes anti-abuse checks, with a per-referrer cap and per-device/IP limits enforced server-side"
      }
    },
    {
      "stride": "Tampering",
      "title": "Credit granted more than once for the same referral (replay or race)",
      "scenario": "An attacker replays the redemption request, or fires several sign-up/redeem calls in parallel, so the ledger write happens repeatedly for one referral. Without an idempotency key and a unique constraint on (referral code, new account), both parties are credited multiple times for a single sign-up, multiplying the payout per fake account.",
      "component": "Referral redemption service / credit ledger",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "When a new account signs up with the code, both accounts receive $10 credit."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-362", "CWE-837"],
      "plainLanguage": "Sending the same 'I used a referral code' request twice at once could pay out twice.",
      "requirement": {
        "title": "Make referral redemption idempotent and atomic",
        "given": "a redemption request for a referral code and a new account",
        "when": "the request is submitted more than once or concurrently",
        "then": "the credit is applied exactly once, enforced by a unique constraint on the (code, redeeming account) pair and a single transactional ledger write"
      }
    },
    {
      "stride": "Tampering",
      "title": "Client-supplied credit amount or referral attribution trusted by the server",
      "scenario": "A mobile client controls the sign-up payload. If the reward amount, currency, referrer id or 'rewardGranted' flag comes from the request rather than being derived server-side from the code, an attacker edits the payload to credit $10,000 instead of $10 or to attribute the referral to an account they control. The design states the payout but not where the amount is decided.",
      "component": "Sign-up API / referral redemption",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        {
          "quote": "both accounts receive $10 credit"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-602", "CWE-20"],
      "plainLanguage": "If the app tells the server how much credit to give, someone could change the number.",
      "requirement": {
        "title": "Derive referral reward server-side",
        "given": "a referral redemption request from a mobile client",
        "when": "the server computes the reward",
        "then": "the amount, currency and referrer identity are looked up server-side from the stored referral code and any client-supplied amount or referrer field is ignored"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Account created on someone else's email address, then taken over",
      "scenario": "Since sign-up only requires an email address with no proof of control, an attacker registers accounts on other people's addresses to harvest referral credits or to pre-seed an account the real owner later tries to claim. The squatted account holds the victim's email (PII) and any credit, and the legitimate owner may be locked out or inherit an attacker-controlled account.",
      "component": "Sign-up flow",
      "likelihood": 4,
      "impact": 3,
      "evidence": [
        {
          "quote": "Sign-up only needs an email address."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-287", "CWE-1392"],
      "plainLanguage": "Anyone could open an account using your email because nobody checks it is really yours.",
      "requirement": {
        "title": "Prove control of the email address at sign-up",
        "given": "a sign-up submitting an email address",
        "when": "the account is created",
        "then": "the account stays unverified and earns no referral credit until a single-use, time-limited verification link sent to that address is used"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Guessable referral codes let attackers enumerate and attribute to real users",
      "scenario": "If codes are short, sequential or derived from a username or user id, an attacker enumerates valid codes to confirm which accounts exist (account existence disclosure) and to attach their fake sign-ups to arbitrary real users, making abuse look organic and spreading payouts across victims' accounts.",
      "component": "Referral code generator",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        {
          "quote": "Each user gets a referral code."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-330", "CWE-204"],
      "plainLanguage": "Easy-to-guess referral codes tell an attacker who has an account and let them use other people's codes.",
      "requirement": {
        "title": "Use unguessable referral codes and uniform responses",
        "given": "referral codes are issued to users",
        "when": "a code is generated or validated",
        "then": "codes contain at least 64 bits of CSPRNG entropy, are not derived from user identifiers, and invalid-code responses are uniform and rate limited so account existence cannot be inferred"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No auditable link between a payout and the sign-up that earned it",
      "scenario": "The design credits both accounts but records no immutable ledger entry tying each $10 to a specific code, redeeming account, timestamp and device signal. When fraud is detected, finance and support cannot prove which credits were earned fraudulently, cannot claw them back selectively, and users can dispute legitimate adjustments. This is a money-moving flow, so attribution is material rather than generic logging hygiene.",
      "component": "Credit ledger",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        {
          "quote": "Referral codes for credits"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-778"],
      "plainLanguage": "Without a clear record of why each $10 was given, you cannot prove or undo fraudulent credits.",
      "requirement": {
        "title": "Append-only referral credit ledger",
        "given": "a referral credit is granted or reversed",
        "when": "the balance changes",
        "then": "an append-only ledger entry records code, referrer, redeemer, amount, timestamp and originating IP/device, and balances are only ever computed from these entries"
      }
    }
  ]
}
```
